class Solution { long long mirror(long long half,bool odd){long long result=half,rest=odd?half/10:half;while(rest){result=result*10+rest%10;rest/=10;}return result;}long long cost(vector<int>& nums,long long target){long long total=0;for(int value:nums)total+=llabs((long long)value-target);return total;}public:long long minimumCost(vector<int>& nums){sort(nums.begin(),nums.end());long long median=nums[nums.size()/2];string text=to_string(median);int length=text.size(),halfLength=(length+1)/2;long long prefix=stoll(text.substr(0,halfLength));vector<long long> candidates={1,999999999};long long power=1;for(int i=0;i<length;++i)power*=10;candidates.push_back(power/10-1);candidates.push_back(power+1);for(long long delta=-1;delta<=1;++delta)if(prefix+delta>0)candidates.push_back(mirror(prefix+delta,length%2));long long answer=LLONG_MAX;for(long long candidate:candidates)if(candidate>=1&&candidate<1000000000LL)answer=min(answer,cost(nums,candidate));return answer;} };
